{"propositions":[{"id":"P1","proposition":"Amends Tennessee Code Annotated, Section 49-3-359(a), by replacing "two hundred dollars ($200)" with "five hundred dollars ($500)".","importance":"core","section":"SECTION 1","source_quote":""two hundred dollars ($200)" and substituting "five hundred dollars ($500)"."},{"id":"P2","proposition":"The act does not appropriate funds and prohibits funds from being obligated or expended pursuant to it unless specifically appropriated by the General Appropriations Act.","importance":"core","section":"SECTION 2","source_quote":"This act is not an appropriation of funds, and funds shall not be obligated

or expended pursuant to this act unless the funds are specifically appropriated by the General

Appropriations Act."},{"id":"P3","proposition":"The act takes effect July 1, 2025.","importance":"supporting","section":"SECTION 3","source_quote":"This act takes effect July 1, 2025, the public welfare requiring it."}]}
